import re
from fractions import Fraction

_NUM = r"\d+(?:\.\d+)?"

_UNITS = {
    "second": 1, "seconds": 1, "sec": 1, "secs": 1, "s": 1,
    "minute": 60, "minutes": 60, "min": 60, "mins": 60, "m": 60,
    "hour": 3600, "hours": 3600, "hr": 3600, "hrs": 3600, "h": 3600,
    "day": 86400, "days": 86400, "d": 86400,
    "week": 604800, "weeks": 604800, "wk": 604800, "wks": 604800, "w": 604800,
}

_COMPONENT_RE = re.compile(r"\s*(" + _NUM + r")\s*([A-Za-z]+)\s*")
_ISO_RE = re.compile(
    r"P"
    r"(?:(?P<W>" + _NUM + r")W)?"
    r"(?:(?P<D>" + _NUM + r")D)?"
    r"(?:T"
    r"(?=\d|\.)"
    r"(?:(?P<H>" + _NUM + r")H)?"
    r"(?:(?P<M>" + _NUM + r")M)?"
    r"(?:(?P<S>" + _NUM + r")S)?"
    r")?"
)
_CLOCK_RE = re.compile(r"(\d+)(?::(\d+))(?::(\d+(?:\.\d+)?))?")


def _round_half_up(value: Fraction) -> int:
    return int((value + Fraction(1, 2)) // 1)


def _check_clock(text: str) -> Fraction:
    m = _CLOCK_RE.fullmatch(text)
    if not m:
        raise ValueError(f"invalid duration: {text!r}")
    h, mi, s = m.group(1), m.group(2), m.group(3)
    if s is None:
        # mm:ss
        minutes, secs = int(h), Fraction(mi)
        if secs >= 60:
            raise ValueError(f"invalid duration: {text!r}")
        return minutes * 60 + secs
    hours, minutes, secs = int(h), int(mi), Fraction(s)
    if minutes >= 60 or secs >= 60:
        raise ValueError(f"invalid duration: {text!r}")
    return hours * 3600 + minutes * 60 + secs


def _parse_iso(text: str) -> Fraction:
    m = _ISO_RE.fullmatch(text)
    if not m or not any(m.group(k) for k in ("W", "D", "H", "M", "S")):
        raise ValueError(f"invalid ISO 8601 duration: {text!r}")
    total = Fraction(0)
    for key, unit in (("W", 604800), ("D", 86400), ("H", 3600), ("M", 60), ("S", 1)):
        val = m.group(key)
        if val is not None:
            total += Fraction(val) * unit
    return total


def _parse_components(text: str) -> Fraction:
    pos = 0
    total = Fraction(0)
    n = len(text)
    count = 0
    while pos < n:
        m = _COMPONENT_RE.match(text, pos)
        if not m or m.end() == pos:
            raise ValueError(f"invalid duration: {text!r}")
        unit = m.group(2).lower()
        if unit not in _UNITS:
            raise ValueError(f"unknown unit {m.group(2)!r}")
        total += Fraction(m.group(1)) * _UNITS[unit]
        pos = m.end()
        count += 1
    if count == 0:
        raise ValueError("empty duration")
    return total


def parse_duration(text: str) -> int:
    """Return the duration described by `text` in whole seconds. See README.md."""
    if not isinstance(text, str):
        raise ValueError("duration must be a string")
    s = text.strip()
    if not s:
        raise ValueError("empty duration")

    if re.fullmatch(r"\d+", s):
        return int(s)
    if s.startswith("P"):
        total = _parse_iso(s)
    elif ":" in s:
        total = _check_clock(s)
    else:
        total = _parse_components(s)
    return _round_half_up(total)

